import { useState } from 'react';
import { JxToggle, JxSlider, JxSwitch, JxDivider, JxSelect, JxBadge } from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  denseLayout: boolean;
  font: string;
}

const themeLabels: Record<ThemeValue, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<ThemeValue>('system');
  const [scale, setScale] = useState(100);
  const [denseLayout, setDenseLayout] = useState(false);
  const [font, setFont] = useState('sans');

  const emit = (next: Partial<AppearanceSettings>) => {
    onChange?.({ theme, scale, denseLayout, font, ...next });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 440,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', color: 'var(--jx-text)' }}>
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: 14 }}>Тема оформления</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => {
            const next = value as ThemeValue;
            setTheme(next);
            emit({ theme: next });
          }}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        value={scale}
        unit="%"
        showOutput
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={denseLayout}
        onChange={(event) => {
          const next = event.target.checked;
          setDenseLayout(next);
          emit({ denseLayout: next });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        options={[
          { value: 'sans', label: 'Inter Tight (по умолчанию)' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={(value) => {
          setFont(value);
          emit({ font: value });
        }}
      />
    </div>
  );
}

